    "note": "古文の内容把握は、①語の意味（古語）、②（注）の情報、③前後の場面の3つを組み合わせて考える。「かばかり」は「これくらい」という意味で、「と心得て」は「と思いこんで」と訳せる。つまり、「これだけ（で足りる）と思って帰った」のである。何を「これだけ」と思ったのかは、（注）にある場所の情報と、後の法師の発言で決まる。",
