    "note": "四つの年号を並べてみる。645＜663＜672＜701 で、きれいに増えている。「645年は大化の改新」「663年は白村江」「672年は壬申の乱」「701年は大宝律令」と、出来事と年号を対にして覚えていれば、取りちがえない。",
